INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-f3cab3594011', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Mettre son logement en location : les règles ont évolué en 2026', 'https://www.service-public.gouv.fr/particuliers/actualites/A18880?xtor=RSS-111', 'Vous souhaitez mettre votre résidence principale en location ? Vous êtes alors soumis à la fiscalité sur les meublés de tourisme. Les règles découlant de la loi Le Meur de 2024 ont évolué en 2026. Service Public vous informe.', 42, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Mettre son logement en location : les règles ont évolué en 2026","url":"https://www.service-public.gouv.fr/particuliers/actualites/A18880?xtor=RSS-111","summary":"Vous souhaitez mettre votre résidence principale en location ? Vous êtes alors soumis à la fiscalité sur les meublés de tourisme. Les règles découlant de la loi Le Meur de 2024 ont évolué en 2026. Service Public vous informe.","published_at":"","topic":"veille","relevance_score":42,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-afd5249b64ae', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Encadrement des loyers : le plafonnement des hausses est prolongé jusqu''au 31 juillet 2027', 'https://www.service-public.gouv.fr/particuliers/actualites/A17566?xtor=RSS-111', 'Le dispositif qui limite les augmentations de loyer dans les communes classées en « zone tendue » est reconduit pour une année. Un décret du 20 juillet 2026 prolonge l''encadrement de l''évolution de certains loyers lors d''une nouvelle location ou du renouvellement d''un bail. Mais dans certaines communes de zone tendue, comme Paris, Bordeaux et Montpellier, un encadrement du niveau des loyers s''applique également. Service Public vous explique.', 22, 'veille', '', '2026-07-28T01:17:59.597Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Encadrement des loyers : le plafonnement des hausses est prolongé jusqu''au 31 juillet 2027","url":"https://www.service-public.gouv.fr/particuliers/actualites/A17566?xtor=RSS-111","summary":"Le dispositif qui limite les augmentations de loyer dans les communes classées en « zone tendue » est reconduit pour une année. Un décret du 20 juillet 2026 prolonge l''encadrement de l''évolution de certains loyers lors d''une nouvelle location ou du renouvellement d''un bail. Mais dans certaines communes de zone tendue, comme Paris, Bordeaux et Montpellier, un encadrement du niveau des loyers s''applique également. Service Public vous explique.","published_at":"","topic":"veille","relevance_score":22,"fetched_at":"2026-07-28T01:17:59.597Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-842122f87c79', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Incendie en Gironde : un appel à la solidarité des entreprises est lancé', 'https://entreprendre.service-public.gouv.fr/actualites/A19011?xtor=RSS-111', 'Dans le cadre des incendies en Gironde, un appel à la solidarité des entreprises a été lancé ce dimanche 27 juillet. Entreprendre Service Public fait le point avec vous.', 15, 'sinistres', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Incendie en Gironde : un appel à la solidarité des entreprises est lancé","url":"https://entreprendre.service-public.gouv.fr/actualites/A19011?xtor=RSS-111","summary":"Dans le cadre des incendies en Gironde, un appel à la solidarité des entreprises a été lancé ce dimanche 27 juillet. Entreprendre Service Public fait le point avec vous.","published_at":"","topic":"sinistres","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-40ef73c768a0', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'La classe prépa-seconde pérennisée à partir de la rentrée 2026', 'https://www.service-public.gouv.fr/particuliers/actualites/A17384?xtor=RSS-111', 'La classe préparatoire à la classe de seconde est destinée à des élèves de troisième admis en seconde ayant besoin de consolider leurs acquis, notamment lorsqu''ils n''ont pas obtenu le diplôme national du brevet. Mise en place à titre expérimental à la rentrée 2024, elle est désormais inscrite dans le code de l''éducation par un décret publié au Journal officiel du 12 juillet 2026.', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"La classe prépa-seconde pérennisée à partir de la rentrée 2026","url":"https://www.service-public.gouv.fr/particuliers/actualites/A17384?xtor=RSS-111","summary":"La classe préparatoire à la classe de seconde est destinée à des élèves de troisième admis en seconde ayant besoin de consolider leurs acquis, notamment lorsqu''ils n''ont pas obtenu le diplôme national du brevet. Mise en place à titre expérimental à la rentrée 2024, elle est désormais inscrite dans le code de l''éducation par un décret publié au Journal officiel du 12 juillet 2026.","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-270e46fa5b94', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Aide pour les travailleurs « grands rouleurs » : prolongation de l’ouverture du guichet', 'https://www.service-public.gouv.fr/particuliers/actualites/A18903?xtor=RSS-111', 'Initialement, le guichet de demande de l’aide carburant pour les travailleurs « grands rouleurs » devait fermer le 30 juillet. La date de clôture vient d’être repoussée. Ce guichet vous permet de demander l’indemnité de 100 euros mise en place pour limiter les effets de la hausse du prix des carburants. Service Public vous présente les différentes modalités pour percevoir cette subvention.', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Aide pour les travailleurs « grands rouleurs » : prolongation de l’ouverture du guichet","url":"https://www.service-public.gouv.fr/particuliers/actualites/A18903?xtor=RSS-111","summary":"Initialement, le guichet de demande de l’aide carburant pour les travailleurs « grands rouleurs » devait fermer le 30 juillet. La date de clôture vient d’être repoussée. Ce guichet vous permet de demander l’indemnité de 100 euros mise en place pour limiter les effets de la hausse du prix des carburants. Service Public vous présente les différentes modalités pour percevoir cette subvention.","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-2061d3c52cfd', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Assistance éducative : chaque enfant devra être accompagné dans la procédure par un avocat', 'https://www.service-public.gouv.fr/particuliers/actualites/A19005?xtor=RSS-111', 'À compter du 6 janvier 2027, la présence d''un avocat sera obligatoire pour assister tout enfant faisant l''objet d''une mesure d''assistance éducative. Actuellement, cette présence est facultative et est conditionnée à la capacité de discernement du mineur.', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Assistance éducative : chaque enfant devra être accompagné dans la procédure par un avocat","url":"https://www.service-public.gouv.fr/particuliers/actualites/A19005?xtor=RSS-111","summary":"À compter du 6 janvier 2027, la présence d''un avocat sera obligatoire pour assister tout enfant faisant l''objet d''une mesure d''assistance éducative. Actuellement, cette présence est facultative et est conditionnée à la capacité de discernement du mineur.","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-80a44e61fa65', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Voyages en train : quelles sont les règles pour vos bagages ?', 'https://www.service-public.gouv.fr/particuliers/actualites/A17752?xtor=RSS-111', 'Vous prenez le train pour voyager cet été ? TGV INOUI, Intercités, OUIGO, TER... Vous devez respecter les règles de la SNCF concernant vos bagages à bord. Service Public vous renseigne.', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Voyages en train : quelles sont les règles pour vos bagages ?","url":"https://www.service-public.gouv.fr/particuliers/actualites/A17752?xtor=RSS-111","summary":"Vous prenez le train pour voyager cet été ? TGV INOUI, Intercités, OUIGO, TER... Vous devez respecter les règles de la SNCF concernant vos bagages à bord. Service Public vous renseigne.","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
