INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-fb01efa236c6', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Vente de fonds de commerce : la procédure de la loi Hamon évolue', 'https://entreprendre.service-public.gouv.fr/actualites/A18893?xtor=RSS-111', 'La loi de simplification de la vie économique assouplit le dispositif de la loi Hamon. Cette dernière a mis en place un mécanisme d’information préalable des salariés dans les entreprises de moins de 250 salariés en cas de vente du fonds de commerce ou de cession de la majorité du capital. L’objectif est d’alléger la procédure afin de réduire la charge des démarches administratives et de renforcer la sécurité juridique des entreprises. Ces nouvelles règles s’appliqueront aux ventes conclues aprè', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Vente de fonds de commerce : la procédure de la loi Hamon évolue","url":"https://entreprendre.service-public.gouv.fr/actualites/A18893?xtor=RSS-111","summary":"La loi de simplification de la vie économique assouplit le dispositif de la loi Hamon. Cette dernière a mis en place un mécanisme d’information préalable des salariés dans les entreprises de moins de 250 salariés en cas de vente du fonds de commerce ou de cession de la majorité du capital. L’objectif est d’alléger la procédure afin de réduire la charge des démarches administratives et de renforcer la sécurité juridique des entreprises. Ces nouvelles règles s’appliqueront aux ventes conclues aprè","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO editorial_watch_items (id, source_id, source_name, source_url, title, url, summary, relevance_score, topic, published_at, fetched_at, payload) VALUES ('watch-87f3c362f4c5', 'service-public-particuliers', 'Service-Public.fr particuliers', 'https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss', 'Micro-entreprise et entreprise individuelle : comprendre la distinction', 'https://entreprendre.service-public.gouv.fr/actualites/A19000?xtor=RSS-111', 'La micro-entreprise et l’entreprise individuelle peuvent souvent être confondues. Elles partagent en effet la même forme juridique puisqu’une micro-entreprise est la version allégée d’une entreprise individuelle : elle bénéficie d’un régime social et d’un régime fiscal simplifiés. Entreprendre Service Public vous explique.', 15, 'veille', '', '2026-07-28T01:17:59.600Z', '{"source_id":"service-public-particuliers","source_name":"Service-Public.fr particuliers","source_url":"https://www.service-public.fr/abonnements/rss/actu-actualites-particuliers.rss","title":"Micro-entreprise et entreprise individuelle : comprendre la distinction","url":"https://entreprendre.service-public.gouv.fr/actualites/A19000?xtor=RSS-111","summary":"La micro-entreprise et l’entreprise individuelle peuvent souvent être confondues. Elles partagent en effet la même forme juridique puisqu’une micro-entreprise est la version allégée d’une entreprise individuelle : elle bénéficie d’un régime social et d’un régime fiscal simplifiés. Entreprendre Service Public vous explique.","published_at":"","topic":"veille","relevance_score":15,"fetched_at":"2026-07-28T01:17:59.600Z"}') ON CONFLICT(url) DO UPDATE SET title = excluded.title, summary = excluded.summary, relevance_score = excluded.relevance_score, topic = excluded.topic, published_at = excluded.published_at, fetched_at = excluded.fetched_at, payload = excluded.payload;
INSERT INTO newsletter_issues (id, slug, title, subject, summary, status, html_url, plain_text, payload, created_at, published_at, sent_at) VALUES ('issue-8ddcceb57b67', 'news/veille-assurance-immeuble-2026-07-28', 'Veille assurance immeuble: veille, contrats et devis', 'ImmeubleAssur - veille assurance immeuble 2026-07-28', 'Resume actionnable des signaux publics utiles aux syndics, bailleurs, SCI et coproprietaires non occupants.', 'published', '/news/veille-assurance-immeuble-2026-07-28', 'Veille assurance immeuble: veille, contrats et devis
